#!/usr/bin/env bash
# SPDX-License-Identifier: MIT
# Prove the AI-attribution gate can fail and stays quiet on clean input: the
# patterns over fixtures, then scan.sh itself over a throwaway git repository.
set -uo pipefail
here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=patterns.sh
. "$here/patterns.sh"
pass=0 fail=0
expect() { # expect <label> <hit|miss> <regex> <text>
    local got=miss
    grep -qiE "$3" <<<"$4" && got=hit
    if [[ "$got" == "$2" ]]; then pass=$((pass + 1)); echo "  ok    $1 ($got)"
    else fail=$((fail + 1)); echo "  FAIL  $1: expected $2, got $got"; fi
}

echo "message and body: must fire on"
expect "co-authored trailer" hit "$ai_pattern" "fix: thing

Co-Authored-By: Claude Opus 5 <noreply@anthropic.com>"
expect "lowercase variant" hit "$ai_pattern" "co-authored-by: claude fable 5.1 <x>"
expect "session trailer" hit "$ai_pattern" "Claude-Session: https://claude.ai/code/session_01ABC"
expect "'Generated with' footer" hit "$ai_pattern" "Some description

🤖 Generated with [Claude Code](https://claude.com/claude-code)"
expect "emphasised 'Generated by' footer" hit "$ai_pattern" "---
_Generated by [Claude Code](https://claude.ai/code/session_01JpBhbbxYrRE2qmzzZ9UjQm)_"
expect "bold footer" hit "$ai_pattern" "**Generated with [Claude Code]**"
expect "bare session url" hit "$ai_pattern" "https://claude.ai/code/session_01SqhNKhTejqWb9Q9YXsx1gh"
expect "session link mid-line" hit "$ai_pattern" "see [the session](https://claude.ai/code/session_01ABC)"
expect "leading whitespace" hit "$ai_pattern" "   Co-Authored-By:   Claude Opus 5 <n@a.com>"
expect "markdown-quoted trailer" hit "$ai_pattern" "> Co-Authored-By: Claude Opus 5 <noreply@anthropic.com>"

echo "message and body: must not fire on"
expect "ordinary commit" miss "$ai_pattern" "plugins: LICENSE notes name the right plugin"
expect "human co-author" miss "$ai_pattern" "feat: x

Co-Authored-By: Alex Hession <alex@example.com>"
expect "inline mention in prose" miss "$ai_pattern" "The gate rejects a \`Co-Authored-By: Claude\` trailer."
expect "word claude alone" miss "$ai_pattern" "docs: claude is a name too"
expect "empty body" miss "$ai_pattern" ""

echo "identity"
expect "assistant as author" hit "$ai_identity" "Claude <noreply@anthropic.com>
Alex Hession <alex@example.com>"
expect "anthropic noreply, other name" hit "$ai_identity" "Claude Opus 5 <noreply@anthropic.com>"
expect "human + GitHub committer" miss "$ai_identity" "Alex Hession <alex@example.com>
GitHub <noreply@github.com>"
expect "a human named Claude" miss "$ai_identity" "Claude Dupont <claude@example.fr>"

echo "opt-out"
expect "annotation with reason" hit "$ai_optout" "ai-attribution-ok: this PR documents the gate"
expect "annotation without reason" miss "$ai_optout" "ai-attribution-ok:"

echo "scan.sh over a real repository"
repo="$(mktemp -d)"
trap 'rm -rf "$repo"' EXIT
git -C "$repo" init -q -b main
gitc() { git -C "$repo" -c user.name="$1" -c user.email="$2" commit -q --allow-empty -m "$3"; }
gitc Alex alex@example.com "base"
base=$(git -C "$repo" rev-parse HEAD)
scan() { # scan <label> <expected exit> <body>
    local rc=0
    (cd "$repo" && BASE="$base" HEAD_SHA=HEAD PR_BODY="$3" bash "$here/scan.sh" >/dev/null) || rc=$?
    if [[ "$rc" -eq "$2" ]]; then pass=$((pass + 1)); echo "  ok    $1 (exit $rc)"
    else fail=$((fail + 1)); echo "  FAIL  $1: expected exit $2, got $rc"; fi
}
gitc Alex alex@example.com "fix: clean"
scan "a clean PR passes" 0 "An ordinary description."
scan "a footer in the body fails" 1 "x

Generated with [Claude Code](https://claude.com/claude-code)"
scan "an opted-out body passes" 0 "ai-attribution-ok: documents the gate
Generated with [Claude Code]"
gitc Claude noreply@anthropic.com "fix: clean message, AI author"
scan "a commit authored as the assistant fails" 1 ""
git -C "$repo" reset -q --hard HEAD~1
gitc Alex alex@example.com "fix: x

Co-Authored-By: Claude Opus 5 <noreply@anthropic.com>"
scan "a co-author trailer fails" 1 ""
base=$(git -C "$repo" rev-parse HEAD)   # the trailer commit is now history
gitc Alex alex@example.com "fix: clean, on top of an old trailer"
scan "a trailer already on the base is not this PR's" 0 ""

echo
echo "pass=$pass fail=$fail"
[[ "$fail" -eq 0 ]]
